#!/bin/sh
# OPA's tests for its parser and compiler (v1/ast), evaluator (v1/topdown, which also runs the YAML cases under
# v1/test/cases), formatter, bundles, planner and semver, as kurtkode's sandbox can run them. The tests listed here open
# a local port or look up a host name, which the sandbox blocks, so they are skipped. Extra arguments go to go test.
exec go test -count=1 -skip '^(TestBuiltinJSONSchemaAllowNet|TestCertSelectionLogic|TestDistributedTracing|TestGetBoolValFromReqObj|TestGetCachingMode|TestGetResponseHeaderDateEmpty|TestHTTPDeleteRequest|TestHTTPEnableJSONOrYAMLDecode|TestHTTPGetRequest|TestHTTPGetRequestAllowNet|TestHTTPGetRequestTlsInsecureSkipVerify|TestHTTPHostHeader|TestHTTPPostRequest|TestHTTPRedirectAllowNet|TestHTTPRedirectDisable|TestHTTPRedirectEnable|TestHTTPSClient|TestHTTPSNoClientCerts|TestHTTPSendCacheDefaultStatusCodesInterQueryCache|TestHTTPSendCacheDefaultStatusCodesIntraQueryCache|TestHTTPSendCaching|TestHTTPSendCustomRequestHeaders|TestHTTPSendInterQueryCaching|TestHTTPSendInterQueryCachingModifiedResp|TestHTTPSendInterQueryCachingNewResp|TestHTTPSendInterQueryForceCaching|TestHTTPSendInterQueryForceCachingRefresh|TestHTTPSendIntraQueryCaching|TestHTTPSendMetrics|TestHTTPSendRaiseError|TestHTTPSendRetryRequest|TestHTTPSendTimeout|TestHTTPWithCustomTransport|TestInitDefaults|TestInsertIntoHTTPSendInterQueryCacheError|TestInterQueryCacheConcurrentModification|TestInterQueryCacheDataClone|TestInterQueryCacheValueClone|TestInterQueryCheckCacheError|TestInvalidKeyError|TestInvalidRetryParam|TestIsJSONType|TestNetLookupIPAddr|TestNewForceCacheParams|TestNewInterQueryCacheValue|TestParseMaxAgeCacheDirective|TestParseTimeout|TestRaisingHTTPClientQueryError|TestRemoteSchema|TestRemoteSchemaHostNotAllowed|TestSetTypesWithPodSchema|TestSetTypesWithSchemaRef|TestSocketHTTPGetRequest|TestTopDownPartialEvalLoopback)$' ./v1/ast/... ./v1/topdown/... ./v1/format/... ./v1/bundle/... ./internal/planner/... ./internal/semver/... "$@"
